  CHECK_RETURN_STATUS(s);

  // write forward
  s = memory_store_->insert(doc);
  CHECK_RETURN_STATUS(s);

  // write scalar index
  s = insert_scalar_indexer(doc);
  if (!s.ok() && s.code() != StatusCode::ALREADY_EXISTS) {
    return s;
