  if (!s.ok() && s != Status::AlreadyExists()) {
    return s;
  }

  auto &mem_block = segment_meta_->writing_forward_block().value();
  mem_block.max_doc_id_ = g_doc_id;
  mem_block.doc_count_ = mem_block.doc_count_ + 1;

  doc_ids_.push_back(g_doc_id);

  return Status::OK();
}

